// This file is generated by AI.

// 生成失败的报错详情弹窗 (历史卡片与工作台任务项共用)。
//
// 为什么要有它: GSOV 的原始报错是给日志看的 —— 颜色转义、星号横幅、几十行搜索
// 路径。铺在卡片或任务项里会把整栏撑爆, 于是列表里只留一行摘要, 全文放到这里看,
// 并且能一键复制去搜/去贴给整合包作者。

import { Button } from '@fluentui/react-components';
import { CopyRegular } from '@fluentui/react-icons';
import { useState } from 'react';

import { AppDialog } from '../components/AppDialog';
import { errorDetail, errorHint } from './errorText';

interface Props {
  /** 报错原文; null 表示不显示弹窗 */
  error: string | null;
  /** 标题下方的说明 (角色 / 类型 / 时间) */
  description?: string;
  onClose: () => void;
}

export function VoiceErrorDialog({ error, description, onClose }: Props) {
  const [copyState, setCopyState] = useState<'idle' | 'ok' | 'fail'>('idle');

  if (!error) return null;

  const detail = errorDetail(error);
  const hint = errorHint(error);

  return (
    <AppDialog
      title="生成失败"
      description={description}
      size="medium"
      height={380}
      onClose={onClose}
      footer={
        <>
          <Button
            appearance="secondary"
            icon={<CopyRegular />}
            title="复制完整报错 (含搜索路径与堆栈)"
            onClick={() => {
              void navigator.clipboard
                .writeText(detail)
                .then(() => setCopyState('ok'))
                .catch(() => setCopyState('fail'));
            }}
          >
            {copyState === 'ok' ? '已复制' : copyState === 'fail' ? '复制失败' : '复制报错'}
          </Button>
          <Button appearance="primary" onClick={onClose}>
            关闭
          </Button>
        </>
      }
    >
      <pre className="voice-error-detail">{detail}</pre>
      {hint && <p className="voice-error-hint">{hint}</p>}
    </AppDialog>
  );
}
